// ===========================================================================================================
// libphext-cs: The Fourth Root - Range Fixture Conformance Tests
// Consumes the shared libphext 0.6.1 range fixtures in tests/fixtures/ranges/
// (see FIXTURES-RANGES.md in the ports program workspace; format digest is
// each case's expected.tsv, generated by calling libphext-rs 0.6.1 itself).
//
// For every case: check the input identity (byte length + SHA-256), then
// apply every op in expected.tsv order against chain 0 of ParseChains:
// parse_point / parse_range check the canonical serialization (or the
// expected parse error), resolve_point checks the (universe, coordinate,
// scalar offset) triple (or the expected resolution error), and
// fetch_point / fetch_range compare result bytes byte-exactly against
// results/NN.txt and check the recorded `resolved` flag against whether
// resolution actually succeeds in this port.
// ===========================================================================================================

using System.Security.Cryptography;
using System.Text;
using Xunit;
using Phext;

namespace Phext.Tests;

public class RangeFixtureTests
{
    private static string FixturesRoot =>
        Path.Combine(AppContext.BaseDirectory, "fixtures", "ranges");

    private static string Sha256Hex(byte[] bytes) =>
        Convert.ToHexString(SHA256.HashData(bytes)).ToLowerInvariant();

    public static IEnumerable<object[]> Cases()
    {
        string[] names =
        {
            "point-basics",
            "offset-form",
            "range-within-scroll",
            "range-cross-scroll",
            "range-multiverse",
            "range-unicode",
        };
        foreach (var name in names) yield return new object[] { name };
    }

    [Theory]
    [MemberData(nameof(Cases))]
    public void RangeFixtureConforms(string caseName)
    {
        string dir = Path.Combine(FixturesRoot, caseName);
        Assert.True(Directory.Exists(dir), $"fixture dir missing: {dir}");

        byte[] inputBytes = File.ReadAllBytes(Path.Combine(dir, "input.phext"));
        string[] lines = File.ReadAllLines(Path.Combine(dir, "expected.tsv"));

        int expectedOps = -1;
        int opCount = 0;
        Chain? chain = null;

        foreach (string line in lines)
        {
            if (line.Length == 0) continue;
            string[] fields = line.Split('\t');
            if (fields[0] == "input_bytes")
            {
                Assert.Equal(int.Parse(fields[1]), inputBytes.Length);
                continue;
            }
            if (fields[0] == "input_sha256")
            {
                Assert.Equal(fields[1], Sha256Hex(inputBytes));
                continue;
            }
            if (fields[0] == "ops")
            {
                expectedOps = int.Parse(fields[1]);
                continue;
            }
            if (fields[0] != "op") continue;

            chain ??= PhextEngine.ParseChains(Encoding.UTF8.GetString(inputBytes))[0];
            opCount++;
            string kind = fields[1];
            string input = fields[2];
            var kv = new Dictionary<string, string>();
            for (int i = 3; i < fields.Length; i++)
            {
                int eq = fields[i].IndexOf('=');
                kv[fields[i].Substring(0, eq)] = fields[i].Substring(eq + 1);
            }

            switch (kind)
            {
                case "parse_point":
                {
                    var parsed = PhextEngine.ParsePointAddress(input);
                    if (kv["error"] == "true")
                    {
                        Assert.True(parsed is null, $"{caseName}: parse_point {input} should fail");
                    }
                    else
                    {
                        Assert.True(parsed is not null, $"{caseName}: parse_point {input} should parse");
                        Assert.Equal(kv["canonical"], parsed!.ToString());
                    }
                    break;
                }
                case "parse_range":
                {
                    var parsed = PhextEngine.ParseRangeAddress(input);
                    if (kv["error"] == "true")
                    {
                        Assert.True(parsed is null, $"{caseName}: parse_range {input} should fail");
                    }
                    else
                    {
                        Assert.True(parsed is not null, $"{caseName}: parse_range {input} should parse");
                        Assert.Equal(kv["canonical"], parsed!.ToString());
                    }
                    break;
                }
                case "resolve_point":
                {
                    var parsed = PhextEngine.ParsePointAddress(input);
                    Assert.True(parsed is not null, $"{caseName}: resolve_point {input} should parse");
                    var resolved = chain.ResolvePoint(parsed!);
                    if (kv["error"] == "true")
                    {
                        Assert.True(resolved is null, $"{caseName}: resolve_point {input} should fail");
                    }
                    else
                    {
                        Assert.True(resolved is not null, $"{caseName}: resolve_point {input} should resolve");
                        string actual = $"{resolved.Value.Universe}|{resolved.Value.Coordinate}|{resolved.Value.Offset}";
                        Assert.Equal(kv["resolve"], actual);
                    }
                    break;
                }
                case "fetch_point":
                {
                    byte[] expectedBytes = File.ReadAllBytes(Path.Combine(dir, kv["file"]));
                    string result = chain.FetchPoint(input);
                    Assert.Equal(expectedBytes, Encoding.UTF8.GetBytes(result));
                    var parsed = PhextEngine.ParsePointAddress(input);
                    bool resolved = parsed is not null && chain.ResolvePoint(parsed) is not null;
                    Assert.True(
                        bool.Parse(kv["resolved"]) == resolved,
                        $"{caseName}: fetch_point {input} resolved flag");
                    break;
                }
                case "fetch_range":
                {
                    byte[] expectedBytes = File.ReadAllBytes(Path.Combine(dir, kv["file"]));
                    string result = chain.FetchRange(input);
                    Assert.Equal(expectedBytes, Encoding.UTF8.GetBytes(result));
                    var parsed = PhextEngine.ParseRangeAddress(input);
                    bool resolved = parsed is not null && chain.ResolveRange(parsed) is not null;
                    Assert.True(
                        bool.Parse(kv["resolved"]) == resolved,
                        $"{caseName}: fetch_range {input} resolved flag");
                    break;
                }
                default:
                    Assert.Fail($"{caseName}: unknown op kind {kind}");
                    break;
            }
        }

        Assert.True(chain is not null, $"{caseName}: no ops consumed");
        Assert.Equal(expectedOps, opCount);
    }
}
